  'Sakan v1: 7 home sections, Showroom, Book a visit, FAQ pages'
FROM templates t
WHERE t.key = 'sakan'
ON CONFLICT (template_id, version) DO NOTHING;

UPDATE templates t SET current_version_id = v.id, updated_at = now()
FROM template_versions v
WHERE t.key = 'sakan' AND v.template_id = t.id AND v.version = 1
  AND t.current_version_id IS DISTINCT FROM v.id;

-- Rollback: DELETE FROM templates WHERE key = 'sakan'; (cascades to its versions and installs).
